import { Hono } from 'hono';
import { streamSSE } from 'hono/streaming';

const app = new Hono();
app.get('/stream', (c) => {
  return streamSSE(c, async (stream) => {
    let i = 0;
    while (true) {
      await stream.writeSSE({ data: JSON.stringify({ i: i++, ts: Date.now() }) });
      await stream.sleep({{interval_ms}});
    }
  });
});

export default app;
